# Python Tutorial: Building a Robust Data Processing Library

## Introduction

This tutorial walks through building a complete, tested Python library for data processing. We'll cover functions, classes, error handling, iterators, decorators, and testing with `unittest` and `pytest`-style assertions. Everything is runnable as-is.

---

## Part 1: Core Functions — Validation and Transformation

Let's start with a module for cleaning raw text data.

```python
# textutils.py

def normalize_whitespace(text: str) -> str:
    """Collapse runs of whitespace into single spaces and strip ends."""
    if not isinstance(text, str):
        raise TypeError(f"Expected str, got {type(text).__name__}")
    return " ".join(text.split())


def slugify(text: str, separator: str = "-") -> str:
    """Convert text into a URL-friendly slug."""
    cleaned = normalize_whitespace(text.lower())
    replacements = {
        "&": "and", "@": "at", "+": "plus", "#": "hash", "$": "dollar",
    }
    for symbol, word in replacements.items():
        cleaned = cleaned.replace(symbol, f" {word} ")
    cleaned = normalize_whitespace(cleaned)
    slug = []
    for ch in cleaned:
        if ch.isalnum():
            slug.append(ch)
        else:
            slug.append(separator)
    result = "".join(slug)
    # Collapse repeated separators
    while separator * 2 in result:
        result = result.replace(separator * 2, separator)
    return result.strip(separator)


def truncate(text: str, max_length: int, ellipsis: str = "...") -> str:
    """Truncate text, appending an ellipsis if it was cut."""
    if max_length < len(ellipsis):
        raise ValueError("max_length must be at least the ellipsis length")
    if len(text) <= max_length:
        return text
    return text[: max_length - len(ellipsis)] + ellipsis
```

### Tests for Part 1

```python
# test_textutils.py
import unittest
from textutils import normalize_whitespace, slugify, truncate


class TestNormalizeWhitespace(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(normalize_whitespace("  hello   world  "), "hello world")

    def test_tabs_and_newlines(self):
        self.assertEqual(normalize_whitespace("a\tb\nc"), "a b c")

    def test_rejects_non_string(self):
        with self.assertRaises(TypeError):
            normalize_whitespace(123)


class TestSlugify(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(slugify("Hello World"), "hello-world")

    def test_symbols(self):
        self.assertEqual(slugify("Tom & Jerry"), "tom-and-jerry")

    def test_custom_separator(self):
        self.assertEqual(slugify("a b c", separator="_"), "a_b_c")

    def test_leading_trailing_separators_removed(self):
        self.assertEqual(slugify("  !!wow!!  "), "wow")


class TestTruncate(unittest.TestCase):
    def test_no_truncation_needed(self):
        self.assertEqual(truncate("short", 10), "short")

    def test_truncates(self):
        self.assertEqual(truncate("abcdefghij", 7), "abc" + "...")

    def test_too_small_max_length(self):
        with self.assertRaises(ValueError):
            truncate("x", 2)


if __name__ == "__main__":
    unittest.main()
```

Run with `python -m unittest test_textutils.py -v`. All tests should pass.

