# Python Tutorial: Building a Robust Data Processing Library

## Introduction

Python is one of the most versatile programming languages available today. In this tutorial, we'll explore core Python concepts by building a practical data processing library. We'll cover functions, classes, error handling, iterators, generators, and testing with `unittest`.

## Part 1: Basic Functions and Data Types

Let's start with simple functions that demonstrate Python's fundamental data types.

```python
def add_numbers(a: float, b: float) -> float:
    """Add two numbers together."""
    return a + b


def is_even(n: int) -> bool:
    """Check if a number is even."""
    return n % 2 == 0


def reverse_string(s: str) -> str:
    """Reverse a string."""
    return s[::-1]
```

### Testing Part 1

```python
import unittest

class TestBasicFunctions(unittest.TestCase):
    def test_add_numbers(self):
        self.assertEqual(add_numbers(2, 3), 5)
        self.assertEqual(add_numbers(-1, 1), 0)
        self.assertAlmostEqual(add_numbers(0.1, 0.2), 0.3, places=7)

    def test_is_even(self):
        self.assertTrue(is_even(4))
        self.assertFalse(is_even(7))
        self.assertTrue(is_even(0))

    def test_reverse_string(self):
        self.assertEqual(reverse_string("hello"), "olleh")
        self.assertEqual(reverse_string(""), "")
        self.assertEqual(reverse_string("a"), "a")
```

## Part 2: Working with Lists and Dictionaries

Lists and dictionaries are Python's workhorse data structures.

```python
def find_max(numbers: list) -> float:
    """Return the maximum value in a list. Raises ValueError on empty list."""
    if not numbers:
        raise ValueError("Cannot find max of an empty list")
    return max(numbers)


def count_words(text: str) -> dict:
    """Count occurrences of each word in a text."""
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts


def merge_dicts(d1: dict, d2: dict) -> dict:
    """Merge two dictionaries, with d2's values taking precedence."""
    result = d1.copy()
    result.update(d2)
    return result
```

### Testing Part 2

```python
class TestDataStructures(unittest.TestCase):
    def test_find_max(self):
        self.assertEqual(find_max([1, 5, 3]), 5)
        self.assertEqual(find_max([-10, -5]), -5)
        with self.assertRaises(ValueError):
            find_max([])

    def test_count_words(self):
        result = count_words("the cat and the dog")
        self.assertEqual(result["the"], 2)
        self.assertEqual(result["cat"], 1)
        self.assertNotIn("bird", result)

    def test_merge_dicts(self):
        result = merge_dicts({"a": 1}, {"a": 2, "b": 3})
        self.assertEqual(result, {"a": 2, "b": 3})
        # Original dict should be unchanged
        self.assertEqual({"a": 1}.get("b"), None)
```

## Part 3: Classes and Object-Oriented Programming

Classes let us bundle data and behavior together.

```python
class DataRecord:
    """Represents a single data record with validation."""

    def __init__(self, name: str, value: float):
        if not name:
            raise ValueError("Name cannot be empty")
        self.name = name
        self.value = value

    def __repr__(self):
        return f"DataRecord(name={self.name!r}, value={self.value})"

    def __eq__(self, other):
        if not isinstance(other, DataRecord):
            return NotImplemented
        return self.name == other.name and self.value == other.value


class DataCollection:
    """A collection of DataRecord objects."""

    def __init__(self):
        self._records = []

    def add(self, record: DataRecord):
        self._records.append(record)

    def __len__(self):
        return len(self._records)

    def __iter__(self):
        return iter(self._records)

    def total_value(self) -> float:
        return sum(r.value for r in self._records)

    def find_by_name(self, name: str):
        for record in self._records:
            if record.name == name:
                return record
        return None
```

